/* =====================================================================
   RENZ STYLE SOLVE - FUNNEL LOADER
   Built 17 Sep 2026, 18:23. Do not edit this file by hand: it is generated by
   build-loader.py from the funnel source and overwritten on every build.

   The page that loads this needs one tag, once:

     <div id="rz-upsell-mount"></div>
     <script src="https://franklow1.github.io/renz-funnel/upsell.js" defer></script>

   Everything else lives here.
   ===================================================================== */
(function(){
  "use strict";
  /* a second copy of this tag on the same page would build a second quiz */
  var FLAG = "__RZ_LOADED_" + "rz_upsell_mount";
  if (window[FLAG]) return;
  window[FLAG] = true;

  var MOUNT_ID = "rz-upsell-mount";
  var CSS  = "\n/* =====================================================================\n   RENZ - THE BUYER - one click upsell\n   Same paper, same type, same button as the sales page. Everything is scoped to\n   #rz-upsell so the builder cannot reach in and this cannot reach out.\n\n   THE TWO BUTTONS BELONG TO GOHIGHLEVEL, NOT TO US.\n   A one click purchase has to be GHL's own element or the card on file is never\n   charged. So: put GHL's buy button and its skip link anywhere on this step, and this\n   page finds them, hides them, and drives them from the buttons below. Selectors are\n   at the top of the script. If it cannot find them it says so in the console rather\n   than failing quietly, which is the mistake that left nine booking buttons dead.\n   ===================================================================== */\n#rz-upsell{\n --ink:#15130F; --graphite:#3D3A34; --pencil:#5C5750;\n --hairline:#D5CFC2;\n --chalk:#F4F1EA; --paper:#FBF9F3;\n --brass:#73572F; --brass-lift:#B58D57;\n --display:\"Newsreader\",\"Libre Caslon Text\",Georgia,serif;\n --text:\"Libre Caslon Text\",\"Times New Roman\",Georgia,serif;\n --micro:\"Cabin\",\"Gill Sans\",\"Gill Sans MT\",system-ui,sans-serif;\n --s2:12px; --s3:18px; --s4:24px; --s5:36px; --s6:48px; --s7:72px;\n --pad:24px; --wrap:620px;\n --ez:cubic-bezier(.2,.7,.2,1); --ezs:cubic-bezier(.16,.84,.24,1);\n}\n#rz-upsell *,#rz-upsell *:before,#rz-upsell *:after{box-sizing:border-box}\n#rz-upsell{position:relative;width:100%;background:var(--chalk);color:var(--graphite);\n font:400 17px/29px var(--text);-webkit-text-size-adjust:100%;text-rendering:optimizeLegibility;\n overflow-x:clip;orphans:2;widows:2;\n background-image:repeating-linear-gradient(0deg,rgba(21,19,15,.03) 0 1px,transparent 1px 4px),\n                  repeating-linear-gradient(90deg,rgba(21,19,15,.022) 0 1px,transparent 1px 4px),\n                  repeating-linear-gradient(90deg,rgba(21,19,15,.018) 0 1px,transparent 1px 23px)}\n#rz-upsell .wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--pad)}\n#rz-upsell section{padding:var(--s7) 0 var(--s6)}\n\n/* the reassurance line, first, because he has just paid */\n#rz-upsell .stamp{font:600 11px/1 var(--micro);letter-spacing:.22em;text-transform:uppercase;\n color:var(--brass);text-align:center;margin:0 0 var(--s4)}\n#rz-upsell .stamp span{display:inline-block;padding:0 14px;position:relative}\n#rz-upsell .stamp span:before,#rz-upsell .stamp span:after{content:\"\";position:absolute;top:50%;\n width:26px;height:1px;background:var(--hairline)}\n#rz-upsell .stamp span:before{right:100%}\n#rz-upsell .stamp span:after{left:100%}\n\n#rz-upsell h1{font-family:var(--display);font-weight:600;font-size:clamp(32px,5.4vw,44px);\n line-height:1.22;letter-spacing:-.02em;color:var(--ink);text-align:center;text-wrap:balance;\n margin:0 auto;max-width:15ch}\n#rz-upsell .sub{font-size:19px;line-height:30px;color:var(--pencil);text-align:center;\n max-width:30ch;margin:var(--s3) auto 0;text-wrap:balance}\n\n/* the film, same frame as the sales page */\n#rz-upsell .film{margin:var(--s5) auto 0;max-width:560px;position:relative;\n background:#0E0D0A;border:1px solid rgba(21,19,15,.18);\n box-shadow:0 1px 0 rgba(255,255,255,.4),0 26px 50px -34px rgba(21,19,15,.5)}\n#rz-upsell .film .ar{position:relative;width:100%;padding-top:56.25%}\n#rz-upsell .film .ar>*{position:absolute;inset:0;width:100%;height:100%}\n#rz-upsell .film .ph{display:flex;align-items:center;justify-content:center;\n background:linear-gradient(160deg,#1A1813,#0E0D0A)}\n#rz-upsell .film .ph i{display:block;width:0;height:0;border-style:solid;\n border-width:13px 0 13px 21px;border-color:transparent transparent transparent rgba(244,241,234,.86)}\n\n/* the argument */\n#rz-upsell .say{margin:var(--s6) auto 0;max-width:34ch}\n#rz-upsell .say p{margin:0 0 var(--s3);font-size:18px;line-height:30px;color:var(--graphite)}\n#rz-upsell .say p:last-child{margin-bottom:0}\n#rz-upsell .say b{font-weight:700;color:var(--ink)}\n#rz-upsell .turn{font-family:var(--display);font-size:23px;line-height:33px;color:var(--ink);\n text-align:center;max-width:24ch;margin:var(--s6) auto 0;text-wrap:balance}\n\n/* the price, stated in words, never on the button */\n#rz-upsell .cost{font:500 14px/22px var(--micro);letter-spacing:.02em;color:var(--pencil);\n text-align:center;margin:var(--s5) auto 0;max-width:36ch}\n\n/* the button, lifted from the sales page so the two feel like one thing */\n#rz-upsell .go{margin:var(--s4) auto 0;padding:0 var(--pad);max-width:508px}\n#rz-upsell .btn{display:block;width:100%;margin:0 auto;padding:20px var(--s4) 19px;border:0;\n border-radius:0;background:var(--ink);color:var(--chalk);text-align:center;text-decoration:none;\n cursor:pointer;touch-action:manipulation;position:relative;overflow:hidden;\n box-shadow:inset 0 0 0 1px rgba(181,141,87,.3);transition:background .45s var(--ez);\n font-family:var(--text)}\n#rz-upsell .btn .l1{display:block;font:600 17px/23px var(--display);color:var(--chalk);\n position:relative;z-index:1}\n#rz-upsell .btn .l2{display:block;max-width:34ch;margin:5px auto 0;font:500 14px/19px var(--micro);\n letter-spacing:.02em;color:rgba(244,241,234,.8);position:relative;z-index:1}\n#rz-upsell .btn:before{content:\"\";position:absolute;inset:0;background:#241F18;transform:scaleX(0);\n transform-origin:left center;transition:transform 520ms var(--ez)}\n#rz-upsell .btn:hover:before{transform:scaleX(1)}\n#rz-upsell .btn:active{transform:scale(.97);transition-duration:120ms}\n#rz-upsell .btn:focus-visible{outline:3px solid var(--brass-lift);outline-offset:3px}\n@media(hover:none){#rz-upsell .btn:hover:before{transform:scaleX(0)}}\n\n/* leaving has to be easy, or he buys nothing and books nothing */\n#rz-upsell .skip{display:block;width:100%;background:none;border:0;padding:var(--s4) 0 0;\n font:500 15px/22px var(--micro);color:var(--pencil);text-align:center;cursor:pointer;\n text-decoration:underline;text-underline-offset:3px;text-decoration-color:var(--hairline)}\n#rz-upsell .skip:hover{color:var(--ink);text-decoration-color:var(--brass-lift)}\n#rz-upsell .skip:focus-visible{outline:3px solid var(--brass-lift);outline-offset:3px}\n\n#rz-upsell .smallprint{font:400 14px/23px var(--micro);color:var(--pencil);text-align:center;\n max-width:40ch;margin:var(--s5) auto 0;padding-bottom:var(--s6)}\n\n/* whatever the builder's own buttons look like, they are never seen */\n#rz-upsell-host{position:absolute!important;left:-9999px!important;top:0!important;\n width:1px!important;height:1px!important;overflow:hidden!important}\n\n@media(min-width:760px){\n  #rz-upsell h1{font-size:52px;line-height:1.16}\n  #rz-upsell .sub{font-size:21px;line-height:33px}\n  #rz-upsell .say p{font-size:19px;line-height:32px}\n}\n@media(prefers-reduced-motion:reduce){\n  #rz-upsell .btn,#rz-upsell .btn:before{transition:none}\n}\n";
  var HTML = "<div id=\"rz-upsell\">\n  <section>\n    <div class=\"wrap\">\n      <p class=\"stamp\"><span>Your call is paid for</span></p>\n\n      <h1>One more thing, then you&rsquo;re done.</h1>\n      <p class=\"sub\">You could stop looking for things altogether.</p>\n\n      <div class=\"film\">\n        <div class=\"ar\">\n          <div class=\"ph\" id=\"rzu-film\" aria-label=\"A short message from Lorenzo\"><i></i></div>\n        </div>\n      </div>\n\n      <div class=\"say\">\n        <p>You&rsquo;ve just sorted out where to buy. Good. There&rsquo;s a level above that, and it&rsquo;s the one I use myself.</p>\n        <p>I have a sourcing agent. He&rsquo;s in China, he&rsquo;s been with me for years, and he can get almost anything.</p>\n        <p>You see something. Anywhere. A jacket on a bloke in the street. A trouser in a window. A photo you saved months ago and never did anything about.</p>\n        <p>You send him the picture. He finds who makes it, tells you what it costs, and gets it to your door.</p>\n        <p><b>Not a copy with somebody else&rsquo;s name stitched on it.</b> The same garment, made properly, with no label.</p>\n      </div>\n\n      <p class=\"turn\">So you stop looking for things. You just point at them.</p>\n\n      <p class=\"cost\">One hundred and ninety nine pounds, once, and he&rsquo;s yours from today.</p>\n\n      <div class=\"go\">\n        <button type=\"button\" class=\"btn\" id=\"rzu-yes\">\n          <span class=\"l1\">Yes, I never want to hunt for a piece again</span>\n          <span class=\"l2\">One tap. Your card is already on file.</span>\n        </button>\n        <button type=\"button\" class=\"skip\" id=\"rzu-no\">No thanks, take me to my calendar</button>\n      </div>\n\n      <p class=\"smallprint\">This is the introduction and the brief that makes him useful to you. It is not the clothes themselves, and he does not deal in counterfeits.</p>\n    </div>\n  </section>\n</div>";

  function mountPoint(){
    var m = document.getElementById(MOUNT_ID);
    if (m) return m;
    /* no mount div in the page: put it where this script tag sits, or failing that,
       at the end of the body, so the funnel never simply fails to appear */
    m = document.createElement('div');
    m.id = MOUNT_ID;
    var s = document.currentScript;
    if (s && s.parentNode) s.parentNode.insertBefore(m, s.nextSibling);
    else (document.body || document.documentElement).appendChild(m);
    return m;
  }

  function paint(){
    try{
      var st = document.createElement('style');
      st.setAttribute('data-rz-funnel','1');
      st.appendChild(document.createTextNode(CSS));
      (document.head || document.documentElement).appendChild(st);
      mountPoint().innerHTML = HTML;
    }catch(e){
      if (window.console && console.error) console.error('[RZ] could not paint the funnel', e);
      return false;
    }
    return true;
  }

  function run(){
    if (!paint()) return;
    /* the funnel's own code, verbatim, with the markup already on the page */
    (function(){
      'use strict';

      /* =============================================================================
         THE TWO SELECTORS. Put GoHighLevel's own one click buy button and its skip
         link anywhere on this step. Give the buy button the custom class rz-buy and
         the skip link rz-skip in the builder, and nothing below needs touching.
         ============================================================================= */
      var BUY  = '.rz-buy, [data-rz-buy]';
      var SKIP = '.rz-skip, [data-rz-skip]';

      /* If the classes have not been set yet, fall back to reading the buttons on the
         page: a one click step usually has exactly two, one of which says no. This is a
         safety net, not the plan, and it says so out loud when it is the thing running. */
      function guess(kind){
        var all = [].slice.call(document.querySelectorAll('a,button'));
        var mine = document.getElementById('rz-upsell');
        all = all.filter(function(el){ return !(mine && mine.contains(el)); });
        var no = /no thanks|no,|skip|not for me|decline|take me to/i;
        var yes = /yes|add|upgrade|buy|get|continue|complete/i;
        for (var i=0;i<all.length;i++){
          var t = (all[i].textContent||'').trim();
          if (!t) continue;
          if (kind === 'skip' && no.test(t)) return all[i];
          if (kind === 'buy'  && yes.test(t) && !no.test(t)) return all[i];
        }
        return null;
      }

      function find(sel, kind){
        var el = null;
        try { el = document.querySelector(sel); } catch(e){}
        if (el) return el;
        el = guess(kind);
        if (el && window.console && console.info){
          console.info('[RZ upsell] no ' + sel + ' on this page, so falling back to the ' +
            kind + ' button that reads "' + (el.textContent||'').trim().slice(0,40) +
            '". Set the custom class in the builder to make this deliberate.');
        }
        return el;
      }

      /* the builder's own controls are moved off screen, never removed: removing them
         would take their handlers with them */
      function stow(el){
        if (!el) return;
        var host = document.getElementById('rz-upsell-host');
        if (!host){
          host = document.createElement('div');
          host.id = 'rz-upsell-host';
          host.setAttribute('aria-hidden','true');
          (document.body || document.documentElement).appendChild(host);
        }
        var wrapper = el.closest('.c-button, .c-wrapper') || el;
        if (wrapper.parentNode !== host) host.appendChild(wrapper);
      }

      /* Guards the BUY only. Leaving must never be blocked: a man whose payment stalls has
         to still be able to reach his calendar, or we lose the booking as well as the sale. */
      var buying = false;
      function wire(ourId, sel, kind){
        var ours = document.getElementById(ourId);
        if (!ours) return;
        var theirs = find(sel, kind);
        if (!theirs){
          if (window.console && console.warn){
            console.warn('[RZ upsell] nothing matches "' + sel + '" and no ' + kind +
              ' button could be found. In the builder, add GoHighLevel’s own ' + kind +
              ' control to this step and give it the custom class ' +
              (kind === 'buy' ? 'rz-buy' : 'rz-skip') + '.');
          }
          return;
        }
        stow(theirs);
        var label = kind === 'buy' ? ours.querySelector('.l1').textContent : '';
        ours.addEventListener('click', function(e){
          e.preventDefault();
          if (kind === 'buy'){
            if (buying) return;                /* one tap means one charge */
            buying = true;
            ours.querySelector('.l1').textContent = 'One moment\u2026';
            ours.setAttribute('aria-busy','true');
          }
          try { theirs.click(); }
          catch(err){
            buying = false;
            if (window.console) console.error('[RZ upsell]', err);
          }
          /* if their handler does nothing at all, give him the button back rather than
             leaving him looking at "one moment" forever */
          if (kind === 'buy'){
            setTimeout(function(){
              if (!buying) return;
              buying = false;
              ours.querySelector('.l1').textContent = label;
              ours.removeAttribute('aria-busy');
            }, 9000);
          }
        });
      }

      /* the film, if a media id has been set */
      var MEDIA = '';
      function film(){
        if (!MEDIA) return;
        var slot = document.getElementById('rzu-film');
        if (!slot) return;
        var p = document.createElement('wistia-player');
        p.setAttribute('media-id', MEDIA);
        slot.parentNode.replaceChild(p, slot);
        if (!document.querySelector('script[src*="player.js"]')){
          var s = document.createElement('script');
          s.src = 'https://fast.wistia.com/player.js';
          s.async = true;
          document.head.appendChild(s);
        }
      }

      function boot(){
        try{
          if (!document.querySelector('meta[name="viewport"]')){
            var mv = document.createElement('meta');
            mv.name = 'viewport';
            mv.content = 'width=device-width,initial-scale=1,viewport-fit=cover';
            (document.head || document.documentElement).appendChild(mv);
          }
        }catch(e){}
        wire('rzu-yes', BUY,  'buy');
        wire('rzu-no',  SKIP, 'skip');
        film();
      }

      if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, {once:true});
      else boot();
    })();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run, {once:true});
  } else {
    run();
  }
})();
